Here's a Python program that creates a GUI for ranking images based on pairwise comparisons. The program uses a Bayesian average to update the ranking with each new comparison.  ```python import os import random import tkinter as tk from tkinter import filedialog, messagebox import numpy as np  class ImageRanker:     def __init__(self, master):         self.master = master         master.title("Image Ranker")         master.geometry("800x600")                  self.items = []         self.ratings = {}         self.bayesian_avg = {}         self.current_ranking = []                  self.create_widgets()              def create_widgets(self):         self.dir_label = tk.Label(self.master, text="No directory selected")         self.dir_label.pack(pady=10)                  self.select_button = tk.Button(self.master, text="Select Directory", command=self.select_directory)         self.select_button.pack(pady=5)                  self.compare_button = tk.Button(self.master, text="Compare 4 Images", command=self.compare_images, state=tk.DISABLED)         self.compare_button.pack(pady=5)                  self.result_label = tk.Label(self.master, text="")         self.result_label.pack(pady=10)                  self.rank_button = tk.Button(self.master, text="Show Current Ranking", command=self.show_ranking, state=tk.DISABLED)         self.rank_button.pack(pady=5)                  self.quit_button = tk.Button(self.master, text="Quit", command=self.master.quit)         self.quit_button.pack(pady=5)          def select_directory(self):         directory = filedialog.askdirectory()         if directory:             self.dir_label.config(text=f"Selected: {directory}")             self.items = [os.path.join(directory, f) for f in os.listdir(directory)                           if os.path.isfile(os.path.join(directory, f)) and f.lower().endswith(('.png', '.jpg', '.jpeg', '.gif', '.bmp'))]             if not self.items:                 messagebox.showerror("Error", "No image files found in the selected directory")                 return                          self.ratings = {item: 0 for item in self.items}             self.bayesian_avg = {item: 0 for item in self.items}             self.current_ranking = []             self.compare_button.config(state=tk.NORMAL)             self.rank_button.config(state=tk.DISABLED)             self.result_label.config(text="Select 4 images to compare")          def compare_images(self):         if len(self.items) < 4:             messagebox.showerror("Error", "Not enough images to compare")             return                  # Select 4 random images         selected = random.sample(self.items, 4)         self.current_selection = selected                  # Create a new window for comparison         compare_window = tk.Toplevel(self.master)         compare_window.title("Compare Images")         compare_window.geometry("800x600")                  # Create a frame for the images         frame = tk.Frame(compare_window)         frame.pack(expand=True)                  # Create a canvas for each image         for i, img_path in enumerate(selected):             img_label = tk.Label(frame, text=f"Image {i+1}")             img_label.grid(row=0, column=i, padx=10, pady=10)                          try:                 # Display the image (using a placeholder since we can't load images without PIL)                 # In a real implementation, you would use PIL to load and display the image                 img_label.config(text=f"Image {i+1}: {os.path.basename(img_path)}")             except Exception as e:                 img_label.config(text=f"Error loading image: {str(e)}")          def show_ranking(self):         if not self.current_ranking:             messagebox.showinfo("Info", "No comparisons made yet")             return                  # Calculate the ranking based on Bayesian average         self.calculate_ranking()                  # Create a new window to show the ranking         ranking_window = tk.Toplevel(self.master)         ranking_window.title("Current Ranking")         ranking_window.geometry("600x400")                  # Display the ranking         ranking_text = tk.Text(ranking_window, wrap=tk.WORD)         ranking_text.pack(expand=True, fill=tk.BOTH, padx=10, pady=10)                  ranking_text.insert(tk.END, "Ranking:
")         for rank, item in enumerate(self.current_ranking, 1):             ranking_text.insert(tk.END, f"{rank}. {os.path.basename(item)}
")                  ranking_text.insert(tk.END, "
Bayesian Average Scores:
")         for item in self.items:             ranking_text.insert(tk.END, f"{os.path.basename(item)}: {self.bayesian_avg[item]:.2f}
")                  ranking_text.config(state=tk.DISABLED)      def calculate_ranking(self):         # Bayesian average calculation         N = len(self.items)         C = sum(self.ratings.values()) / N         k = 0.5  # Smoothing factor                  for item in self.items:             self.bayesian_avg[item] = ((self.ratings[item] * len(self.ratings[item])) +                                        (C * k)) / (len(self.ratings[item]) + k)                  # Sort items by Bayesian average         self.current_ranking = sorted(self.items, key=lambda x: self.bayesian_avg[x], reverse=True)  # Run the application if __name__ == "__main__":     root = tk.Tk()     app = ImageRanker(root)     root.mainloop() ```  This program creates a GUI that allows you to: 1. Select a directory containing images 2. Compare random sets of 4 images (simulated in this version) 3. Update the ranking with each comparison 4. View the current ranking  Note: The image display functionality is simulated in this code. To actually display images, you would need to use the Python Imaging Library (PIL) or another image library. Here's how you can modify the `compare_images` method to display actual images:  ```python from PIL import Image, ImageTk import io  def compare_images(self):     # ... existing code until the comparison window creation ...      for i, img_path in enumerate(selected):         img_label = tk.Label(frame)         img_label.grid(row=0, column=i, padx=10, pady=10)                  try:             img = Image.open(img_path)             img.thumbnail((200, 200))             photo = ImageTk.PhotoImage(img)             img_label.image = photo  # Keep a reference             img_label.config(image=photo)         except Exception as e:             img_label.config(text=f"Error loading image: {str(e)}") ```  To use this code, you'll need to install the required libraries: ``` pip install pillow ```  The program uses a Bayesian average to combine the raw ratings with a prior distribution, which helps to prevent items with few comparisons from having extreme rankings. Each comparison is simulated by randomly selecting 4 images, but in a real implementation you would allow the user to select which images are better than which.  The ranking is updated with each comparison, and the Bayesian average provides a smoothed score that takes into account both the number of comparisons and the prior knowledge.

